class Exercise {
    // 값이 바뀌는 줄을 실행 결과와 비교해요.
    static String run(int id) {
        // 첫 명언이 삭제된 뒤의 목록이에요.
        int[] ids={2,4}; String[] texts={"keep","try"};
        for(int i=0;i<ids.length;i++) if(i==id)return texts[i];
        // 없는 ID는 실패로 알려줘요.
        return "missing";
    }
}
